using MySqlConnector;
using Library.Web.Models;
namespace Library.Web.Services;
public sealed class LibraryStore
{
 private readonly string _cs;
 public LibraryStore(IConfiguration config){_cs=config.GetConnectionString("DefaultConnection")??"Server=localhost;Port=3306;Database=library;User=root;Password=higanbana;";EnsureSchema();}
 private MySqlConnection Open(){var c=new MySqlConnection(_cs);c.Open();return c;}
 private void EnsureSchema(){var b=new MySqlConnectionStringBuilder(_cs);var db=b.Database;b.Database="";using(var s=new MySqlConnection(b.ConnectionString)){s.Open();using var q=s.CreateCommand();q.CommandText=$"CREATE DATABASE IF NOT EXISTS `{db}`";q.ExecuteNonQuery();}using var c=Open();using var q2=c.CreateCommand();q2.CommandText=@"CREATE TABLE IF NOT EXISTS Books(BookId INT AUTO_INCREMENT PRIMARY KEY,Isbn VARCHAR(60),Title VARCHAR(200) NOT NULL,Author VARCHAR(160),Category VARCHAR(100),TotalCopies INT NOT NULL,AvailableCopies INT NOT NULL); CREATE TABLE IF NOT EXISTS Students(MemberId INT AUTO_INCREMENT PRIMARY KEY,StudentId VARCHAR(60) NOT NULL UNIQUE,FullName VARCHAR(180) NOT NULL,Course VARCHAR(160),Status VARCHAR(30) NOT NULL DEFAULT 'Active'); CREATE TABLE IF NOT EXISTS Loans(LoanId INT AUTO_INCREMENT PRIMARY KEY,BookId INT NOT NULL,MemberId INT NOT NULL,BorrowedDate DATE NOT NULL,DueDate DATE NOT NULL,ReturnedDate DATE NULL,FOREIGN KEY(BookId) REFERENCES Books(BookId),FOREIGN KEY(MemberId) REFERENCES Students(MemberId));";q2.ExecuteNonQuery();}
 public IReadOnlyList<Book> Books{get{using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT BookId,Isbn,Title,Author,Category,TotalCopies,AvailableCopies FROM Books ORDER BY Title";using var r=q.ExecuteReader();var x=new List<Book>();while(r.Read())x.Add(new Book{BookId=r.GetInt32(0),Isbn=r.IsDBNull(1)?"":r.GetString(1),Title=r.GetString(2),Author=r.IsDBNull(3)?"":r.GetString(3),Category=r.IsDBNull(4)?"":r.GetString(4),TotalCopies=r.GetInt32(5),AvailableCopies=r.GetInt32(6)});return x;}}
 public IReadOnlyList<Member> Members{get{using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT MemberId,StudentId,FullName,Course,Status FROM Students ORDER BY FullName";using var r=q.ExecuteReader();var x=new List<Member>();while(r.Read())x.Add(new Member{MemberId=r.GetInt32(0),MemberNumber=r.GetString(1),FullName=r.GetString(2),Course=r.IsDBNull(3)?"":r.GetString(3),Status=r.GetString(4)});return x;}}
 public IReadOnlyList<LoanRow> Loans{get{using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT l.LoanId,l.BookId,l.MemberId,l.BorrowedDate,l.DueDate,l.ReturnedDate,b.Title,s.FullName FROM Loans l JOIN Books b ON b.BookId=l.BookId JOIN Students s ON s.MemberId=l.MemberId ORDER BY l.BorrowedDate DESC,l.LoanId DESC";using var r=q.ExecuteReader();var x=new List<LoanRow>();while(r.Read())x.Add(new LoanRow{LoanId=r.GetInt32(0),BookId=r.GetInt32(1),MemberId=r.GetInt32(2),BorrowedDate=r.GetDateTime(3),DueDate=r.GetDateTime(4),ReturnedDate=r.IsDBNull(5)?null:r.GetDateTime(5),BookTitle=r.GetString(6),MemberName=r.GetString(7)});return x;}}
 public void AddBook(Book x){using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO Books(Isbn,Title,Author,Category,TotalCopies,AvailableCopies) VALUES(@isbn,@title,@author,@category,@total,@total)";q.Parameters.AddWithValue("@isbn",x.Isbn);q.Parameters.AddWithValue("@title",x.Title.Trim());q.Parameters.AddWithValue("@author",x.Author);q.Parameters.AddWithValue("@category",x.Category);q.Parameters.AddWithValue("@total",x.TotalCopies);q.ExecuteNonQuery();}
 public void AddMember(Member x){using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO Students(StudentId,FullName,Course,Status) VALUES(@id,@name,@course,@status)";q.Parameters.AddWithValue("@id",x.MemberNumber.Trim());q.Parameters.AddWithValue("@name",x.FullName.Trim());q.Parameters.AddWithValue("@course",x.Course);q.Parameters.AddWithValue("@status",x.Status);q.ExecuteNonQuery();}
 public void Borrow(int bookId,int memberId,DateTime due){using var c=Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT AvailableCopies FROM Books WHERE BookId=@book FOR UPDATE";q.Parameters.AddWithValue("@book",bookId);var stock=q.ExecuteScalar();if(stock is null)throw new InvalidOperationException("Select a book.");if(Convert.ToInt32(stock)<1)throw new InvalidOperationException("This book is currently unavailable.");using var add=c.CreateCommand();add.Transaction=tx;add.CommandText="INSERT INTO Loans(BookId,MemberId,BorrowedDate,DueDate) VALUES(@book,@member,CURDATE(),@due);UPDATE Books SET AvailableCopies=AvailableCopies-1 WHERE BookId=@book";add.Parameters.AddWithValue("@book",bookId);add.Parameters.AddWithValue("@member",memberId);add.Parameters.AddWithValue("@due",due.Date);add.ExecuteNonQuery();tx.Commit();}
 public void Return(int loanId){using var c=Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="UPDATE Loans SET ReturnedDate=CURDATE() WHERE LoanId=@id AND ReturnedDate IS NULL";q.Parameters.AddWithValue("@id",loanId);q.ExecuteNonQuery();using var q2=c.CreateCommand();q2.Transaction=tx;q2.CommandText="UPDATE Books b JOIN Loans l ON l.BookId=b.BookId SET b.AvailableCopies=b.AvailableCopies+1 WHERE l.LoanId=@id AND l.ReturnedDate=CURDATE()";q2.Parameters.AddWithValue("@id",loanId);q2.ExecuteNonQuery();tx.Commit();}
}
